content.solution_code:
class Spaceship {
    #fuelLevel;
    #shieldStrength;
    #maxFuel = 100;
    #maxShield = 50;

    constructor(initialFuel, initialShield) {
        this.#fuelLevel = Math.min(initialFuel, this.#maxFuel);
        this.#shieldStrength = Math.min(initialShield, this.#maxShield);
    }

    refuel(amount) {
        if (amount > 0) {
            this.#fuelLevel = Math.min(this.#fuelLevel + amount, this.#maxFuel);
        }
    }

    reinforceShields(amount) {
        if (amount > 0) {
            this.#shieldStrength = Math.min(this.#shieldStrength + amount, this.#maxShield);
        }
    }

    getFuelStatus() {
        return `Fuel: ${this.#fuelLevel}/${this.#maxFuel}`;
    }

    getShieldStatus() {
        return `Shields: ${this.#shieldStrength}/${this.#maxShield}`;
    }
}

